DG.put("hikaaitaan/3",{"n":3,"title":null,"title_roman":null,"page":2567,"blocks":[{"type":"verse","number":[1],"number_text":"੧।","page":2567,"lines":[{"gurmukhi":"ਕਿ ਰੋਜ਼ੀ ਦਿਹੰਦ ਅਸਤੁ ਰਾਜ਼ਕ ਰਹੀਮ।","roman":"Ki rozee dihand astu raazak raheem |","meaning_en":"He is the giver of sustenance, the Provider, the Merciful;","page":2567,"meaning_status":"draft"},{"gurmukhi":"ਰਹਾਈ ਦਿਹੋ ਰਹਿਨੁਮਾਏ ਕਰੀਮ। ੧।","roman":"Rahaaee diho rahinumaae kareem | 1 |","meaning_en":"the giver of release, the guide, the Generous.","page":2567,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":2567,"lines":[{"gurmukhi":"ਦਿਲ ਅਫ਼ਜ਼ਾਇ ਦਾਨਸ਼ ਦਿਹੋ ਦਾਦਗਰ।","roman":"Dil afzaai daanash diho daadgar |","meaning_en":"He gladdens the heart, gives wisdom and dispenses justice;","page":2567,"meaning_status":"draft"},{"gurmukhi":"ਰਜ਼ਾ ਬਖ਼ਸ਼ ਰੋਜ਼ੀ ਦਿਹੋ ਹਰ ਹੁਨਰ। ੨।","roman":"Razaa bakhash rozee diho har hunar | 2 |","meaning_en":"He gives contentment, sustenance and every skill.","page":2567,"meaning_status":"draft"}]},{"type":"verse","number":[3],"number_text":"੩।","page":2567,"lines":[{"gurmukhi":"ਹਿਕਾਯਤ ਸ਼ੁਨੀਦਮ ਯਕੇ ਨੇਕ ਜ਼ਨ।","roman":"Hikaayat shuneedam yake nek zan |","meaning_en":"I have heard a tale of a good woman,","page":2567,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਸ਼ਮਸ਼ਾਦ ਕੱਦੇ ਬ ਜੋਏ ਚਮਨ। ੩।","roman":"Chu shamshaad kadde ba joe chaman | 3 |","meaning_en":"tall as a box-tree beside a garden stream.","page":2567,"meaning_status":"draft","note":"ਸ਼ਮਸ਼ਾਦ: the box-tree, image of a tall, graceful figure."}]},{"type":"verse","number":[4],"number_text":"੪।","page":2569,"lines":[{"gurmukhi":"ਕਿ ਓ ਰਾ ਪਦਰ ਰਾਜਹੇ ਉਤਰ ਦੇਸ਼।","roman":"Ki o raa padar raajhe utar desh |","meaning_en":"Her father was a king of the northern land,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਬ ਸ਼ੀਰੀਂ ਜ਼ੁਬਾਂ ਹਮ ਚ ਇਖ਼ਲਾਸ ਕੇਸ਼। ੪।","roman":"Ba sheereen zubaan ham cha ikhlaas kesh | 4 |","meaning_en":"sweet of tongue and devoted in faith.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":2569,"lines":[{"gurmukhi":"ਕਿ ਆਮਦ ਬਰਾਏ ਹਮਹ ਗੁਸਲ ਗੰਗ।","roman":"Ki aamad baraae hamah gusal gang |","meaning_en":"He came to bathe in the Ganges,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਕੈਬਰ ਕਮਾਂ ਹਮ ਚੁ ਤੀਰੇ ਤੁਫ਼ੰਗ। ੫।","roman":"Chu kaibar kamaan ham chu teere tufang | 5 |","meaning_en":"swift like an arrow from a bow or a musket's shot.","page":2569,"meaning_status":"draft","note":"Simile left as printed; its point (swiftness) is uncertain."}]},{"type":"verse","number":[6],"number_text":"੬।","page":2569,"lines":[{"gurmukhi":"ਹਮੀ ਖ਼ਾਸਤ ਕਿ ਓ ਰਾ ਸ੍ਵਯੰਬਰ ਕੁਨਮ।","roman":"Hamee khaasat ki o raa svayanbar kunam |","meaning_en":"He wished: \"I will hold a swayamvar for her;","page":2569,"meaning_status":"draft","note":"ਸ੍ਵਯੰਬਰ: a ceremony where a princess chooses her husband."},{"gurmukhi":"ਕਸੇ ਈਂ ਪਸੰਦ ਆਯਦ ਓ ਰਾ ਦਿਹਮ। ੬।","roman":"Kase een pasand aayad o raa diham | 6 |","meaning_en":"whoever pleases her, to him I will give her.\"","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[7],"number_text":"੭।","page":2569,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਸੁਖ਼ਨ ਦੁਖ਼ਤਰੇ ਨੇਕ ਤਨ।","roman":"Bigoyad sukhan dukhatre nek tan |","meaning_en":"He spoke to his daughter, fair of form:","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਕਸੇ ਤੋ ਪਸੰਦ ਆਯਦ ਓ ਰਾ ਬਕੁਨ। ੭।","roman":"Kase to pasand aayad o raa bakun | 7 |","meaning_en":"\"Whoever pleases you, choose him.\"","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[8],"number_text":"੮।","page":2569,"lines":[{"gurmukhi":"ਨਿਸ਼ਾਦੰਦ ਬਰ ਕਾਖ ਓ ਹਫ਼ਤ ਖ�ਨ।","roman":"Nishaadand bar kaakh o hafat kha(?)na |","meaning_en":"They seated her in a palace of seven storeys,","page":2569,"flags":[{"code":"0xa2","reason":"unresolved: one occurrence (Zafarnama); glyph shape and page rendering disagree"}],"meaning_status":"draft","note":"ਹਫ਼ਤ ਖ�ਨ: printed so (a character is damaged); read as 'seven storeys'."},{"gurmukhi":"ਚੁ ਮਾਹੇ ਮਹੀ ਆਫ਼ਤਾਬੇ ਯਮਨ। ੮।","roman":"Chu maahe mahee aaftaabe yaman | 8 |","meaning_en":"like the moon on earth, the sun of Yemen.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":2569,"lines":[{"gurmukhi":"ਦਹਾਨੇ ਦੁਹਦ ਰਾ ਦਹਨ ਬਰ ਕੁਸ਼ਾਦ।","roman":"Dahaane duhad raa dahan bar kushaad |","meaning_en":"The mouths of the drums were opened,","page":2569,"meaning_status":"draft","note":"ਦਹਾਨੇ ਦੁਹਦ: read as 'mouths of the drums' (duhul); uncertain."},{"gurmukhi":"ਜਵਾਬੇ ਸੁਖ਼ਨ ਰਾ ਉਜ਼ਰ ਬਰ ਨਿਹਾਦ। ੯।","roman":"Javaabe sukhan raa uzar bar nihaad | 9 |","meaning_en":"and the herald set forth the matter:","page":2569,"meaning_status":"draft","note":"ਜਵਾਬੇ ਸੁਖ਼ਨ ਰਾ ਉਜ਼ਰ ਬਰ ਨਿਹਾਦ: uncertain."}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2569,"lines":[{"gurmukhi":"ਕਿ ਈਂ ਰਾਜਹੇ ਰਾਜਹਾ ਬੇਸ਼ੁਮਾਰ।","roman":"Ki een raajhe raajhaa beshumaar |","meaning_en":"\"These are kings, kings without number,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਵਕਤੇ ਤਰੱਦਦ ਬਿਆ ਮੁਖ਼ਤਹਕਾਰ। ੧੦।","roman":"Ki vakte tarddad biaa mukhtahkaar | 10 |","meaning_en":"skilled in action at the time of struggle.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":2569,"lines":[{"gurmukhi":"ਕਸੇ ਤੋ ਪਸੰਦ ਆਯਦਤ ਈਂ ਜ਼ਮਾਂ।","roman":"Kase to pasand aaydat een zamaan |","meaning_en":"Whichever of them pleases you now,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਵਜ਼ਾਂ ਪਸ ਬ ਦਾਮਾਦੀ ਆਯਦ ਹੁਮਾਂ। ੧੧।","roman":"Vazaan pas ba daamaadee aayad humaan | 11 |","meaning_en":"he shall afterwards become our son-in-law.\"","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":2569,"lines":[{"gurmukhi":"ਨੁਮਾਦੰਦ ਬ ਓ ਰਾਜਹਾਂ ਬੇਸ਼ੁਮਾਰ।","roman":"Numaadand ba o raajhaan beshumaar |","meaning_en":"They showed her countless kings;","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਪਸੰਦਸ਼ ਨਿਯਾਮਦ ਕਸੇ ਕਾਰ ਬਾਰ। ੧੨।","roman":"Pasandash niyaamad kase kaar baar | 12 |","meaning_en":"none of them pleased her at all.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":2569,"lines":[{"gurmukhi":"ਹਮ ਆਖ਼ਰ ਯਕੇ ਰਾਜਹੇ ਸੁਭਟ ਸਿੰਘ।","roman":"Ham aakhar yake raajhe subhat singh |","meaning_en":"At last one king, Subhat Singh,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਪਸੰਦ ਆਮਦਸ਼ ਹਮ ਚੁ ਗੁਰਰਾ ਨਿਹੰਗ। ੧੩।","roman":"Pasand aamdash ham chu gurraa nihang | 13 |","meaning_en":"pleased her, a warrior like a roaring crocodile.","page":2569,"meaning_status":"draft","note":"ਨਿਹੰਗ: 'crocodile', used for a fearless warrior."}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2569,"lines":[{"gurmukhi":"ਹਮਹ ਉਮਦਹੇ ਰਾਜਹਾ ਪੇਸ਼ ਖਾਂਦ।","roman":"Hamah umadhe raajhaa pesh khaand |","meaning_en":"The king called all the chief kings before him","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਜੁਦਾ ਬਰ ਜੁਦਾ ਦਉਰ ਮਜਲਸ ਨਿਸ਼ਾਂਦ। ੧੪।","roman":"Judaa bar judaa daur majlas nishaand | 14 |","meaning_en":"and seated them one by one around the assembly.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":2569,"lines":[{"gurmukhi":"ਬ ਪੁਰਸ਼ੀਦ ਕਿ ਏ ਦੁਖ਼ਤਰੇ ਨੇਕ ਖ਼ੋਇ।","roman":"Ba pursheed ki e dukhatre nek khoi |","meaning_en":"He asked, \"O daughter of good nature,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰਾ ਕਸ ਪਸੰਦ ਆਯਦ ਅਜ਼ੀਹਾਂ ਬਜੋਇ। ੧੫।","roman":"Turaa kas pasand aayad azeehaan bajoi | 15 |","meaning_en":"look among these: who pleases you?\"","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":2569,"lines":[{"gurmukhi":"ਰਵਾਂ ਕਰਦੁ ਜ਼ੁਨਾਰ ਦਾਰਾਨ ਪੇਸ਼।","roman":"Ravaan kardu zunaar daaraan pesh |","meaning_en":"He sent the wearers of the sacred thread ahead,","page":2569,"meaning_status":"draft","note":"ਜ਼ੁਨਾਰ ਦਾਰਾਨ: 'thread-wearers', i.e. Brahmins."},{"gurmukhi":"ਬਿਗੋਯਦ ਕਿ ਈਂ ਰਾਜਹੇ ਉਤਰ ਦੇਸ਼। ੧੬।","roman":"Bigoyad ki een raajhe utar desh | 16 |","meaning_en":"who said, \"This is the daughter of the king of the northern land,","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":2569,"lines":[{"gurmukhi":"ਕਿ ਓ ਨਾਮ ਬਸਤਸ਼ ਬਛਤਰਾ ਮਤੀ।","roman":"Ki o naam bastash bachhatraa matee |","meaning_en":"and her name is Bachhatra Mati,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਮਾਹੇ ਫ਼ਲਕ ਆਫ਼ਤਾਬੇ ਮਹੀ। ੧੭।","roman":"Chu maahe falak aaftaabe mahee | 17 |","meaning_en":"like the moon of the sky and the sun of the earth.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":2569,"lines":[{"gurmukhi":"ਅਜ਼ੀ ਰਾਜਹਾਂ ਕਸ ਨਿਯਾਮਦ ਨਜ਼ਰ।","roman":"Azee raajhaan kas niyaamad nazar |","meaning_en":"If none of these kings has come into your sight,","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਵਜ਼ਾਂ ਪਸ ਅਜ਼ੀਂ ਹਾਂ ਬੁਬੀਂ ਪੁਰ ਗੁਹਰ। ੧੮।","roman":"Vazaan pas azeen haan bubeen pur guhar | 18 |","meaning_en":"then look at these others, O precious one.\"","page":2569,"meaning_status":"draft","note":"ਪੁਰ ਗੁਹਰ: 'full of pearls'; uncertain who is addressed."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":2569,"lines":[{"gurmukhi":"ਨਜ਼ਰ ਕਰਦ ਬਰ ਰਾਜਹਾ ਨਾਜ਼ਨੀਂ।","roman":"Nazar karad bar raajhaa naazneen |","meaning_en":"The graceful one looked at the kings;","page":2569,"meaning_status":"draft"},{"gurmukhi":"ਪਸੰਦਸ਼ ਨਿਯਾਮਦ ਕਸੇ ਦਿਲ ਨਗੀਂ। ੧੯।","roman":"Pasandash niyaamad kase dil nageen | 19 |","meaning_en":"none pleased her or won her heart.","page":2569,"meaning_status":"draft"}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2571,"lines":[{"gurmukhi":"ਸ੍ਵਯੰਬਰ ਵਜ਼ਾਂ ਰੋਜ਼ ਮਉਕੂਫ਼ ਗਸ਼ਤ।","roman":"Svayanbar vazaan roz maukoof gashat |","meaning_en":"The swayamvar was halted for that day;","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਨਾਜ਼ਮ ਬੁ ਬਰਖ਼ਾਸਤ ਦਰਵਾਜ਼ਹ ਬਸਤ। ੨੦।","roman":"Ki naazam bu barkhaasat darvaazah basat | 20 |","meaning_en":"the steward rose and shut the gate.","page":2571,"meaning_status":"draft","note":"ਨਾਜ਼ਮ: 'manager/governor'."}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":2571,"lines":[{"gurmukhi":"ਕਿ ਰੋਜ਼ੇ ਦਿਗਰ ਸ਼ਾਹਿ ਜ਼ਰਰੀਂ ਸਿਪਹਰ।","roman":"Ki roze digar shaahi zarreen siphar |","meaning_en":"The next day, when the king of the golden sky","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਬਰ ਅਉਰੰਗ ਬਰਾਮਦ ਚੁ ਰਉਸ਼ਨ ਗੁਹਰ। ੨੧।","roman":"Bar aurang baraamad chu raushan guhar | 21 |","meaning_en":"rose onto his throne like a shining pearl,","page":2571,"meaning_status":"draft","note":"i.e. the sun rose."}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2571,"lines":[{"gurmukhi":"ਦਿਗਰ ਰੋਜ਼ ਹੇ ਰਾਜਹਾ ਖ਼ਾਸਤੰਦ।","roman":"Digar roz he raajhaa khaastand |","meaning_en":"the kings were called again,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਦਿਗਰ ਗੂਨਹ ਬਾਜ਼ਾਰ ਆਰਾਸਤੰਦ। ੨੨।","roman":"Digar goonah baazaar aaraastand | 22 |","meaning_en":"and the market was arrayed in another fashion.","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2571,"lines":[{"gurmukhi":"ਨਜ਼ਰ ਕੁਨ ਬਰੋਏ ਤੁ ਏ ਦਿਲਰੁਬਾਇ।","roman":"Nazar kun baroe tu e dilrubaai |","meaning_en":"\"Look at their faces, O heart-stealer;","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿਰਾ ਤੋ ਨਜ਼ਰ ਦਰ ਬਿਯਾਯਦ ਬਜਾਇ। ੨੩।","roman":"Kiraa to nazar dar biyaayad bajaai | 23 |","meaning_en":"whoever is rightly pleasing in your sight, choose him.\"","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2571,"lines":[{"gurmukhi":"ਬ ਪਹਿਨ ਅੰਦਰ ਆਮਦ ਗੁਲੇ ਅੰਜਮਨ।","roman":"Ba pahin andar aamad gule anjman |","meaning_en":"The rose of the assembly came out into the open,","page":2571,"meaning_status":"draft","note":"ਪਹਿਨ: 'wide, open ground'."},{"gurmukhi":"ਕਿ ਜ਼ਰ ਆਬ ਰੰਗ ਅਸਤੁ ਸੀਮਾਬ ਤਨ। ੨੪।","roman":"Ki zar aab rang astu seemaab tan | 24 |","meaning_en":"gold-hued and silver-bodied.","page":2571,"meaning_status":"draft","note":"ਸੀਮਾਬ: 'quicksilver'."}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":2571,"lines":[{"gurmukhi":"ਰਵਾਂ ਗਸ਼ਤ ਦਰ ਰਾਜਹਾ ਬੇਸ਼ੁਮਾਰ।","roman":"Ravaan gashat dar raajhaa beshumaar |","meaning_en":"She moved among the countless kings,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਗੁਲੇ ਸੁਰਖ਼ ਚੂੰ ਗੁੰਬਜ਼ੇ ਨਉ ਬਹਾਰ। ੨੫।","roman":"Gule surakh choon gunbze nau bahaar | 25 |","meaning_en":"like a red rose, a bud of the new spring.","page":2571,"meaning_status":"draft","note":"ਗੁੰਬਜ਼: lit. 'dome'; read as 'bud'; uncertain."}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2571,"lines":[{"gurmukhi":"ਬ ਦੁਜ਼ਦੀਦ ਦਿਲ ਰਾਜਹਾ ਬੇਸ਼ੁਮਾਰ।","roman":"Ba duzdeed dil raajhaa beshumaar |","meaning_en":"She stole the hearts of countless kings;","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਬਿਅਫ਼ਤਦ ਜ਼ਿਮੀ ਚੂੰ ਯਲੇ ਕਾਰਜ਼ਾਰ। ੨੬।","roman":"Biaftad zimee choon yale kaarzaar | 26 |","meaning_en":"they fell to the ground like warriors in battle.","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2571,"lines":[{"gurmukhi":"ਬਿਜ਼ਦ ਬਾਂਗ ਬਰ ਵੈ ਕਿ ਖ਼ਾਤੂਨ ਖ਼ੇਸ਼।","roman":"Bizad baang bar vai ki khaatoon khesh |","meaning_en":"The herald cried out to him: \"This lady","page":2571,"meaning_status":"draft","note":"ਬਰ ਵੈ ... ਖ਼ਾਤੂਨ ਖ਼ੇਸ਼: uncertain who is called and how 'khesh' (own) applies."},{"gurmukhi":"ਕਿ ਈਂ ਉਮਦਹੇ ਰਾਜਹਾ ਉਤਰ ਦੇਸ਼। ੨੭।","roman":"Ki een umadhe raajhaa utar desh | 27 |","meaning_en":"is of the chief king of the northern land,","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":2571,"lines":[{"gurmukhi":"ਵਜ਼ਾਂ ਦੁਖ਼ਤਰ ਹਸਤ ਈਂ ਬਛਤਰਾ ਮਤੀ।","roman":"Vazaan dukhtar hasat een bachhatraa matee |","meaning_en":"and that daughter is this Bachhatra Mati,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਮਾਹੇ ਫ਼ਲਕ ਹਮ ਚੁ ਹੂਰੋ ਪਰੀ। ੨੮।","roman":"Chu maahe falak ham chu hooro paree | 28 |","meaning_en":"like the moon of the sky, like a houri or a fairy.","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2571,"lines":[{"gurmukhi":"ਸ੍ਵਯੰਬਰ ਦਰਾਮਦ ਚੁ ਮਾਹੇ ਫ਼ਲਕ।","roman":"Svayanbar daraamad chu maahe falak |","meaning_en":"She has come to the swayamvar like the moon of the sky,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਫਰਿਸ਼ਤਹ ਸਿਫ਼ਤ ਓ ਚੁ ਜ਼ਾਤਸ਼ ਮਲਕ। ੨੯।","roman":"Pharishtah sifat o chu zaatash malak | 29 |","meaning_en":"angelic in nature, an angel in her very being.","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":2571,"lines":[{"gurmukhi":"ਕਿਰਾ ਦੌਲਤ ਇਕਬਾਲ ਯਾਰੀ ਦਿਹਦ।","roman":"Kiraa daulat ikbaal yaaree dihad |","meaning_en":"Whoever is befriended by wealth and fortune,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਈਂ ਮਾਹਰੋ ਕਾਮਗਾਰੀ ਦਿਹਦ। ੩੦।","roman":"Ki een maahro kaamgaaree dihad | 30 |","meaning_en":"to him this moon-faced one will grant fulfilment.\"","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2571,"lines":[{"gurmukhi":"ਪਸੰਦ ਆਮਦ ਓ ਰਾਜਹ ਸੁਭਟ ਸਿੰਘ ਨਾਮ।","roman":"Pasand aamad o raajah subhat singh naam |","meaning_en":"The king named Subhat Singh pleased her,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਰਉਸ਼ਨ ਤਬੀਯਤ ਸਲੀਖ਼ਤ ਮੁਦਾਮ। ੩੧।","roman":"Ki raushan tabeeyat saleekhat mudaam | 31 |","meaning_en":"bright of nature and ever well-mannered.","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":2571,"lines":[{"gurmukhi":"ਰਵਾਂ ਕਰਦ ਬਰ ਵੈ ਵਕੀਲਸ ਗਿਰਾਂ।","roman":"Ravaan karad bar vai vakeelas giraan |","meaning_en":"She sent to him a worthy envoy:","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਏ ਸ਼ਾਹ ਸ਼ਾਹਾਨ ਰਉਸ਼ਨ ਜ਼ਮਾਂ। ੩੨।","roman":"Ki e shaah shaahaan raushan zamaan | 32 |","meaning_en":"\"O king of kings, light of the age,","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2571,"lines":[{"gurmukhi":"ਕਿ ਈਂ ਤਰਜ਼ ਲਾਲਾਇ ਬਰਗੇ ਸਮਨ।","roman":"Ki een taraz laalaai barge saman |","meaning_en":"this one, like a tulip and a jasmine petal,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਲਾਇਕ ਸੁਮਾਨ ਅਸਤ ਈਂ ਰਾ ਬਕੁਨ। ੩੩।","roman":"Ki laaik sumaan asat een raa bakun | 33 |","meaning_en":"is worthy of you; make her yours.\"","page":2571,"meaning_status":"draft","note":"ਲਾਇਕ ਸੁਮਾਨ: read as 'worthy of you' (laaiq-e shuma); uncertain."}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2571,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਯਕੇ ਖ਼ਾਨਹ ਬਾਨੂ ਮਰਾਸਤ।","roman":"Bigoyad yake khaanah baanoo maraasat |","meaning_en":"He said, \"I have a lady of the house,","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਚਸ਼ਮੇ ਅਜ਼ੋ ਹਰਦੁ ਆਹੂ ਤਰਾਸਤ। ੩੪।","roman":"Ki chashme azo hardu aahoo taraasat | 34 |","meaning_en":"whose two eyes are fresher than a deer's.","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":2571,"lines":[{"gurmukhi":"ਕਿ ਹਰਗਿਜ਼ ਮਨ ਈਂ ਰਾ ਨ ਕਰਦਮ ਕਬੂਲ।","roman":"Ki hargiz man een raa na kardam kabool |","meaning_en":"I will never accept this one;","page":2571,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਕਉਲੇ ਕੁਰਾਂ ਅਸਤ ਕਸਮੇ ਰਸੂਲ। ੩੫।","roman":"Ki kaule kuraan asat kasme rasool | 35 |","meaning_en":"this is my word on the Quran, an oath by the Prophet.\"","page":2571,"meaning_status":"draft"}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":2573,"lines":[{"gurmukhi":"ਬ ਗੋਸ਼ ਅੰਦਰ ਆਮਦ ਅਜ਼ੀਂ ਨ ਸੁਖ਼ਨ।","roman":"Ba gosh andar aamad azeen na sukhan |","meaning_en":"When this refusal reached her ears,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬਜੁੰਬਸ਼ ਦਰਾਮਦ ਜ਼ਨੇ ਨੇਕ ਤਨ। ੩੬।","roman":"Bajunbash daraamad zane nek tan | 36 |","meaning_en":"the woman of fair form was stirred to action:","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":2573,"lines":[{"gurmukhi":"ਕਸੇ ਫ਼ਤਹ ਮਾਰਾ ਕੁਨਦ ਵਕਤ ਕਾਰ।","roman":"Kase fatah maaraa kunad vakat kaar |","meaning_en":"\"Whoever defeats me at the time of battle,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਵਜ਼ਾਂ ਸ਼ਾਹਿ ਮਾਰਾ ਸ਼ਵਦ ਈਂ ਦਿਯਾਰ। ੩੭।","roman":"Vazaan shaahi maaraa shavad een diyaar | 37 |","meaning_en":"he shall be my lord, and this land his.\"","page":2573,"meaning_status":"draft","note":"uncertain."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":2573,"lines":[{"gurmukhi":"ਬ ਕੋਸ਼ੀਦ ਮੈਦਾਨ ਜੋਸ਼ੀਦ ਜੰਗ।","roman":"Ba kosheed maidaan josheed jang |","meaning_en":"She went out to the field, eager for battle,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬ ਪੋਸ਼ੀਦ ਖ਼ਫ਼ਤਾਨ ਪੋਲਾਦ ਰੰਗ। ੩੮।","roman":"Ba posheed khaftaan polaad rang | 38 |","meaning_en":"and put on a steel-coloured war-coat.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2573,"lines":[{"gurmukhi":"ਨਿਸ਼ਸਤਹ ਬਰ ਆਂ ਰਥ ਚੁ ਮਾਹੇ ਮੁਨੀਰ।","roman":"Nishastah bar aan rath chu maahe muneer |","meaning_en":"She sat on her chariot like the shining moon;","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬੁਬਸਤੰਦ ਸ਼ਮਸ਼ੇਰ ਜੁਸਤੰਦ ਤੀਰ। ੩੯।","roman":"Bubastand shamsher justand teer | 39 |","meaning_en":"she girded on her sword and took up her arrows.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2573,"lines":[{"gurmukhi":"ਬ ਮੈਦਾਂ ਦਰ ਆਮਦ ਜੁ ਗੁਰਰੀਦ ਸ਼ੇਰ।","roman":"Ba maidaan dar aamad ju gurreed sher |","meaning_en":"She came into the field like a roaring lion,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਸ਼ੇਰ ਅਸਤ ਸ਼ੇਰ ਅਫ਼ਕਨੋ ਦਿਲ ਦਲੇਰ। ੪੦।","roman":"Chu sher asat sher afakno dil daler | 40 |","meaning_en":"a lion, a slayer of lions, bold of heart.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2573,"lines":[{"gurmukhi":"ਬ ਪੋਸ਼ੀਦ ਖ਼ੁਫ਼ਤਾਨ ਜੋਸ਼ੀਦ ਜੰਗ।","roman":"Ba posheed khuftaan josheed jang |","meaning_en":"She put on her war-coat, eager for battle,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬ ਕੋਸ਼ੀਦ ਮੈਦਾਨ ਤੀਰੋ ਤੁਫ਼ੰਗ। ੪੧।","roman":"Ba kosheed maidaan teero tufang | 41 |","meaning_en":"and fought on the field with arrow and musket.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":2573,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੀਰ ਬਾਰਾ ਕੁਨਦ ਕਾਰਜ਼ਾਰ।","roman":"Chunaa teer baaraa kunad kaarzaar |","meaning_en":"She rained such arrows in the battle","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਲਸ਼ਕਰ ਬਕਾਰ ਆਮਦਸ਼ ਬੇਸ਼ੁਮਾਰ। ੪੨।","roman":"Ki lashkar bakaar aamdash beshumaar | 42 |","meaning_en":"that countless of the army were slain.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":2573,"lines":[{"gurmukhi":"ਚੁਨਾ ਬਾਨ ਬਾਰੀਦ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Chunaa baan baareed teero tufang |","meaning_en":"She rained such shafts, arrows and musket-shots","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬਸੁੋ ਮਰਦਮਾਂ ਮੁਰਦਹ ਸ਼ੁਦ ਜਾਇ ਜੰਗ। ੪੩।","roman":"Baso maradmaan murdah shud jaai jang | 43 |","meaning_en":"that many men lay dead on the battlefield.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":2573,"lines":[{"gurmukhi":"ਸਹੇ ਨਾਮ ਗਜ ਸਿੰਘ ਦਰਾਮਦ ਬਜੰਗ।","roman":"Sahe naam gaj singh daraamad bajang |","meaning_en":"A king named Gaj Singh came to battle,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਕੈਬਰ ਕਮਾ ਹਮ ਚੁ ਤੀਰੋ ਤੁਫ਼ੰਗ। ੪੪।","roman":"Chu kaibar kamaa ham chu teero tufang | 44 |","meaning_en":"like an arrow from a bow or a musket's shot.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":2573,"lines":[{"gurmukhi":"ਬਜੁੰਬਸ਼ ਦਰਾਮਦ ਚੁ ਅਫ਼ਰੀਤ ਮਸਤ।","roman":"Bajunbash daraamad chu afreet masat |","meaning_en":"He came storming like a drunken demon,","page":2573,"meaning_status":"draft","note":"ਅਫ਼ਰੀਤ: 'afreet', a demon."},{"gurmukhi":"ਯਕੇ ਗੁਰਜ਼ ਅਜ਼ ਫ਼ੀਲ ਪੈਕਰ ਬ ਦਸਤ। ੪੫।","roman":"Yake guraz az feel paikar ba dasat | 45 |","meaning_en":"a mace in his hand as huge as an elephant.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":2573,"lines":[{"gurmukhi":"ਯਕੇ ਤੀਰ ਜ਼ਦ ਬਾਨੂਏ ਪਾਕ ਮਰਦ।","roman":"Yake teer zad baanooe paak marad |","meaning_en":"The pure lady, heroic as a man, shot one arrow,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਗਜ ਸਿੰਘ ਅਜ਼ ਅਸਪ ਆਮਦ ਬ ਗਰਦ। ੪੬।","roman":"Ki gaj singh az asap aamad ba garad | 46 |","meaning_en":"and Gaj Singh fell from his horse into the dust.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":2573,"lines":[{"gurmukhi":"ਦਿਗਰ ਰਾਜਹ ਰਨ ਸਿੰਘ ਦਰਾਮਦ ਬ ਰੋਸ਼।","roman":"Digar raajah ran singh daraamad ba rosh |","meaning_en":"Another king, Ran Singh, came in anger,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਪਰਵਾਨਹੇ ਚੂੰ ਦਰਾਮਦ ਬਜੋਸ਼। ੪੭।","roman":"Ki parvaanhe choon daraamad bajosh | 47 |","meaning_en":"rushing in fervour like a moth to the flame.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":2573,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੇਗ ਜ਼ਦ ਬਾਨੂਏ ਸ਼ੇਰ ਤਨ।","roman":"Chunaa teg zad baanooe sher tan |","meaning_en":"The lion-bodied lady struck such a sword-blow","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਰਨ ਸਿੰਘ ਚੁ ਸਰਵੇ ਚਮਨ। ੪੮।","roman":"Biaftaad ran singh chu sarve chaman | 48 |","meaning_en":"that Ran Singh fell like a cypress of the garden.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":2573,"lines":[{"gurmukhi":"ਯਕੇ ਸ਼ਹਿਰ ਅੰਬੇਰ ਦਿਗਰ ਜੋਧਪੁਰ।","roman":"Yake shahir anber digar jodhpur |","meaning_en":"One king came from the city of Amber, another from Jodhpur;","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ਰਾਮੀਦਹ ਬਾਨੋ ਚੁ ਰਖ਼ਸਿੰਦਹ ਦੁਰ। ੪੯।","roman":"Kharaameedah baano chu rakhsindah dur | 49 |","meaning_en":"the lady moved gracefully, like a glittering pearl.","page":2573,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":2573,"lines":[{"gurmukhi":"ਬਿਜ਼ਦ ਤੇਗ ਬਾ ਜ਼ੋਰ ਬਾਨੋ ਸਿਪਰ।","roman":"Bizad teg baa zor baano sipar |","meaning_en":"The lady struck her sword with force upon the shields,","page":2573,"meaning_status":"draft"},{"gurmukhi":"ਬ ਬਰਖ਼ੇਜ਼ ਸ਼ੋਲਹ ਬਸੇ ਚੂੰ ਗਹੁਰ। ੫੦।","roman":"Ba barkhez sholah base choon gahur | 50 |","meaning_en":"and many sparks flew up like jewels.","page":2573,"meaning_status":"draft","note":"ਗਹੁਰ: read as 'gauhar' (jewel); uncertain."}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2575,"lines":[{"gurmukhi":"ਸਿਯਮ ਰਾਜਹ ਬੂੰਦੀ ਦਰ ਆਮਦ ਦਲੇਰ।","roman":"Siyam raajah boondee dar aamad daler |","meaning_en":"Third, the king of Bundi came, bold,","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਬਰ ਬੱਚਹ ਆਹੂ ਚੁ ਗੁਰਰੀਦ ਸ਼ੇਰ। ੫੧।","roman":"Chu bar bacchah aahoo chu gurreed sher | 51 |","meaning_en":"like a roaring lion upon a fawn.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2575,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੀਰ ਜ਼ਦ ਹਰ ਦੋ ਅਬਰੂ ਸਿਕੰਜ।","roman":"Chunaa teer zad har do abroo sikanj |","meaning_en":"She shot such an arrow, knitting both her brows,","page":2575,"meaning_status":"draft","note":"ਹਰ ਦੋ ਅਬਰੂ ਸਿਕੰਜ: 'both brows knitted'; may instead mean the arrow struck between his brows; uncertain."},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਅਮਰ ਸਿੰਘ ਚੁ ਸ਼ਾਖੇ ਤੁਰੰਜ। ੫੨।","roman":"Biaftaad amar singh chu shaakhe turanj | 52 |","meaning_en":"that Amar Singh fell like a citron branch.","page":2575,"meaning_status":"draft","note":"Amar Singh is evidently the king of Bundi."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":2575,"lines":[{"gurmukhi":"ਚੁਅਮ ਰਾਜਹ ਜੈ ਸਿੰਘ ਦਰ ਆਮਦ ਮੁਸਾਫ਼।","roman":"Chuam raajah jai singh dar aamad musaaf |","meaning_en":"Fourth, king Jai Singh came to the battle-line,","page":2575,"meaning_status":"draft","note":"ਮੁਸਾਫ਼: 'battle-line'."},{"gurmukhi":"ਬਜੋਸ਼ ਅੰਦਰੀਂ ਸ਼ੁਦ ਚੁ ਅਜ਼ ਕੋਹਕਾਫ਼। ੫੩।","roman":"Bajosh andreen shud chu az kohkaaf | 53 |","meaning_en":"in fury as if from Mount Qaf.","page":2575,"meaning_status":"draft","note":"ਕੋਹਕਾਫ਼: the mythical Mount Qaf."}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":2575,"lines":[{"gurmukhi":"ਹੁਮਾਂ ਖ਼ੁਰਦ ਸ਼ਰਬਤ ਕਿ ਯਾਰੇ ਚੁਅਮ।","roman":"Humaan khurad sharbat ki yaare chuam |","meaning_en":"He too drank the same draught, he the fourth companion,","page":2575,"meaning_status":"draft","note":"i.e. he met the same fate; uncertain."},{"gurmukhi":"ਜ਼ਿ ਜੈ ਸਿੰਘ ਪਸੇ ਯਕ ਨਿਆਮਦ ਕਦਮ। ੫੪।","roman":"Zi jai singh pase yak niaamad kadam | 54 |","meaning_en":"and after Jai Singh no one came forward a single step.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":2575,"lines":[{"gurmukhi":"ਯਕੋ ਸ਼ਹਿ ਫਿਰੰਗੋ ਪਿਲੰਦੇ ਦਿਗਰ।","roman":"Yako shahi phirango pilande digar |","meaning_en":"One, the king of the Franks, another of Pilanda,","page":2575,"meaning_status":"draft","note":"ਫਿਰੰਗ: Europeans. ਪਿਲੰਦੇ: unclear name (perhaps Holland); uncertain."},{"gurmukhi":"ਬ ਮੈਦਾਂ ਦਰਾਮਦ ਚੁ ਸ਼ੇਰੇ ਬਬਰ। ੫੫।","roman":"Ba maidaan daraamad chu shere babar | 55 |","meaning_en":"came into the field like tigers.","page":2575,"meaning_status":"draft","note":"ਸ਼ੇਰੇ ਬਬਰ: 'tiger/lion'."}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2575,"lines":[{"gurmukhi":"ਸਿਯਮ ਸ਼ਾਹਿ ਅੰਗਰੇਜ਼ ਚੂੰ ਆਫ਼ਤਾਬ।","roman":"Siyam shaahi angrez choon aaftaab |","meaning_en":"Third, the king of the English, like the sun;","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਚੁਅਮ ਸ਼ਾਹਿ ਹਬਸ਼ੀ ਚੁ ਮਗਰੇ ਦਰ ਆਬ। ੫੬।","roman":"Chuam shaahi habshee chu magre dar aab | 56 |","meaning_en":"fourth, the king of Abyssinia, like a crocodile in water.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2575,"lines":[{"gurmukhi":"ਯਕੇ ਰਾ ਬਿਜ਼ਦ ਨੇਜ਼ਹ ਮੁਸ਼ਤੇ ਦਿਗਰ।","roman":"Yake raa bizad nezah mushte digar |","meaning_en":"One she struck with a spear, another with her fist,","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਸਿਯਮ ਰਾ ਬ ਪਾਓ ਚੁਅਮ ਰਾ ਸਿਪਰ। ੫੭।","roman":"Siyam raa ba paao chuam raa sipar | 57 |","meaning_en":"the third with her foot, the fourth with her shield.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":2575,"lines":[{"gurmukhi":"ਚੁਨਾ ਮੇ ਬਿਅਫ਼ਤਦ ਨ ਬਰਖ਼ਾਸਤ ਬਾਜ਼।","roman":"Chunaa me biaftad na barkhaasat baaz |","meaning_en":"They fell so that they never rose again;","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਸੂਏ ਆਸਮਾਂ ਜਾਨ ਪਰਵਾਜ਼ ਸਾਜ਼। ੫੮।","roman":"Sooe aasmaan jaan parvaaz saaz | 58 |","meaning_en":"their souls took flight toward the sky.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":2575,"lines":[{"gurmukhi":"ਦਿਗਰ ਕਸ ਨਿਯਾਮਦ ਤਮੰਨਾਇ ਜੰਗ।","roman":"Digar kas niyaamad tamannaai jang |","meaning_en":"No one else had any desire for battle;","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਪੇਸ਼ੇ ਨਿਯਾਮਦ ਦਿਲਾਵਰ ਨਿਹੰਗ। ੫੯।","roman":"Ki peshe niyaamad dilaavar nihang | 59 |","meaning_en":"no bold warrior came forward.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":2575,"lines":[{"gurmukhi":"ਸ਼ਬੇ ਸ਼ਹਿ ਸ਼ਬਿਸਤਾ ਚੂੰ ਦਰ ਆਮਦ ਬਫ਼ਉਜ।","roman":"Shabe shahi shabistaa choon dar aamad bafauj |","meaning_en":"When the king of night came with his army to his night-chamber,","page":2575,"meaning_status":"draft","note":"i.e. the moon and stars; night fell."},{"gurmukhi":"ਸਿਪਹ ਖ਼ਾਨਹ ਆਮਦ ਹਮਹ ਮਉਜ ਮਉਜ। ੬੦।","roman":"Sipah khaanah aamad hamah mauj mauj | 60 |","meaning_en":"the troops went home, wave upon wave.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":2575,"lines":[{"gurmukhi":"ਬ ਰੋਜ਼ੇ ਦਿਗਰ ਰਉਸ਼ਨੀਅਤ ਪਨਾਹ।","roman":"Ba roze digar raushneeat panaah |","meaning_en":"The next day the refuge of light","page":2575,"meaning_status":"draft","note":"i.e. the sun."},{"gurmukhi":"ਬ ਅਉਰੰਗ ਦਰ ਆਮਦ ਚੁ ਅਉਰੰਗ ਸ਼ਾਹ। ੬੧।","roman":"Ba aurang dar aamad chu aurang shaah | 61 |","meaning_en":"came onto his throne like a king on his throne.","page":2575,"meaning_status":"draft","note":"ਅਉਰੰਗ: 'throne'; ਅਉਰੰਗ ਸ਼ਾਹ may also hint at Aurangzeb; uncertain."}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2575,"lines":[{"gurmukhi":"ਦੁ ਸੂਏ ਯਲਾਂ ਹਮਹ ਬਸਤੰਦ ਕਮਰ।","roman":"Du sooe yalaan hamah bastand kamar |","meaning_en":"On both sides the warriors girded their waists,","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਬ ਮੈਦਾਨ ਜੁਸਤੰਦ ਸਿਪਰ ਬਰ ਸਿਪਰ। ੬੨।","roman":"Ba maidaan justand sipar bar sipar | 62 |","meaning_en":"and on the field they clashed, shield against shield.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2575,"lines":[{"gurmukhi":"ਬਗੁਰਰੀਦ ਆਮਦ ਦੁ ਅਬਰੇ ਮੁਸਾਫ਼।","roman":"Bagurreed aamad du abre musaaf |","meaning_en":"Two clouds of battle came thundering;","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਯਕੇ ਗਸ਼ਤਹ ਬਾਯਲ ਯਕੇ ਗਸ਼ਤ ਜ਼ਾਫ਼। ੬੩।","roman":"Yake gashtah baayal yake gashat zaaf | 63 |","meaning_en":"one became wounded, the other grew weak.","page":2575,"meaning_status":"draft","note":"ਬਾਯਲ: read as 'ghaayal' (wounded); ਜ਼ਾਫ਼: 'weak'; uncertain."}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":2575,"lines":[{"gurmukhi":"ਚਕਾਚਾਕ ਬਰਖ਼ਾਸਤ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Chakaachaak barkhaasat teero tufang |","meaning_en":"Arrows and musket-shots rang out, clash upon clash;","page":2575,"meaning_status":"draft","note":"ਚਕਾਚਾਕ: sound-word."},{"gurmukhi":"ਖ਼ਤਾਖ਼ਤ ਦਰਾਮਦ ਹਮਹ ਰੰਗ ਰੰਗ। ੬੪।","roman":"Khataakhat daraamad hamah rang rang | 64 |","meaning_en":"blows fell, smack upon smack, of every kind,","page":2575,"meaning_status":"draft","note":"ਖ਼ਤਾਖ਼ਤ: sound-word."}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":2575,"lines":[{"gurmukhi":"ਜ਼ਿ ਤੀਰੋ ਜ਼ਿ ਤੋਪੋ ਜ਼ਿ ਤੇਗੋ ਤਬਰ।","roman":"Zi teero zi topo zi tego tabar |","meaning_en":"from arrows, cannon, swords and axes,","page":2575,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿ ਨੇਜ਼ਹ ਵ ਨਾਚਖ਼ ਵ ਨਾਵਕ ਸਿਪਰ। ੬੫।","roman":"Zi nezah va naachakh va naavak sipar | 65 |","meaning_en":"from spears, short spears, darts and shields.","page":2575,"meaning_status":"draft","note":"ਨਾਚਖ਼: a short spear; ਨਾਵਕ: a small arrow."}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2575,"lines":[{"gurmukhi":"ਯਕੇ ਦੇਵ ਆਮਦ ਕਿ ਜ਼ਾਗੋ ਨਿਸ਼ਾਂ।","roman":"Yake dev aamad ki zaago nishaan |","meaning_en":"A demon came, with the mark of a crow,","page":2575,"meaning_status":"draft","note":"ਜ਼ਾਗੋ ਨਿਸ਼ਾਂ: 'crow-marked', perhaps crow-black or with a crow banner; uncertain."},{"gurmukhi":"ਚੁ ਗੁਰਰੀਦ ਸ਼ੇਰ ਹਮ ਚੁ ਪੀਲੇ ਦਮਾਂ। ੬੬।","roman":"Chu gurreed sher ham chu peele damaan | 66 |","meaning_en":"like a roaring lion and a trumpeting elephant.","page":2575,"meaning_status":"draft"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2577,"lines":[{"gurmukhi":"ਕੁਨਦ ਤੀਰੋ ਬਾਰਾਂ ਚੁ ਬਾਰਾਂਨ ਮੇਗ।","roman":"Kunad teero baaraan chu baaraann meg |","meaning_en":"He rained arrows like rain from the clouds;","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਬਰਖ਼ਸ਼ ਅੰਦਰਾਂ ਅਬਰ ਚੂੰ ਬਰਕ ਤੇਗ। ੬੭।","roman":"Barkhash andraan abar choon barak teg | 67 |","meaning_en":"his sword flashed like lightning in a cloud.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2577,"lines":[{"gurmukhi":"ਬ ਜੋਸ਼ ਅੰਦਰ ਆਮਦ ਦਹਾਨੇ ਦੁਹਲ।","roman":"Ba josh andar aamad dahaane duhal |","meaning_en":"The mouths of the drums grew loud,","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਪੁਰ ਗਸ਼ਤ ਬਾਜ਼ਾਰ ਜਾਏ ਅਜ਼ਲ। ੬੮।","roman":"Chu pur gashat baazaar jaae azal | 68 |","meaning_en":"as the market-place of death filled up.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2577,"lines":[{"gurmukhi":"ਹਰਾਂ ਕਸ ਕਿ ਪਰਰਾ ਸ਼ਵਦ ਤੀਰ ਸ਼ਸਤ।","roman":"Haraan kas ki parraa shavad teer shasat |","meaning_en":"Every feathered arrow loosed from the thumb-ring","page":2577,"meaning_status":"draft","note":"ਸ਼ਸਤ: the archer's thumb-ring; uncertain."},{"gurmukhi":"ਬਸਦ ਪਹਿਲੂਏ ਪੀਲ ਮਰਦਾਂ ਗੁਜ਼ਸ਼ਤ। ੬੯।","roman":"Basad pahilooe peel mardaan guzshat | 69 |","meaning_en":"passed through the sides of a hundred elephants and men.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2577,"lines":[{"gurmukhi":"ਹੁਮਾਂ ਕਸ ਬਸੇ ਤੀਰ ਜ਼ਦ ਬਰ ਕਜ਼ਾਂ।","roman":"Humaan kas base teer zad bar kazaan |","meaning_en":"That same demon was struck by many arrows from her,","page":2577,"meaning_status":"draft","note":"uncertain who shoots whom."},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਦੇਵੇ ਚੁ ਕਰਖੇ ਗਿਰਾਂ। ੭੦।","roman":"Biaftaad deve chu karkhe giraan | 70 |","meaning_en":"and the demon fell like a heavy mass.","page":2577,"meaning_status":"draft","note":"ਕਰਖੇ ਗਿਰਾਂ: unclear; uncertain."}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":2577,"lines":[{"gurmukhi":"ਦਿਗਰ ਦੇਵ ਬਰਗਸ਼ਤ ਬਿਯਾਮਦ ਬਜੰਗ।","roman":"Digar dev baragshat biyaamad bajang |","meaning_en":"Another demon turned and came to battle,","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਸ਼ੇਰੇ ਅਜ਼ੀਮੋ ਹਮ ਚੁ ਬਰਾਂ ਪਿਲੰਗ। ੭੧।","roman":"Chu shere azeemo ham chu baraan pilang | 71 |","meaning_en":"like a great lion and like a fierce leopard.","page":2577,"meaning_status":"draft","note":"ਬਰਾਂ: read as 'fierce'; uncertain."}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2577,"lines":[{"gurmukhi":"ਚੁਨਾ ਜ਼ਖ਼ਮ ਗੋਪਾਲ ਅੰਦਾਖ਼ਤ ਸਖ਼ਤ।","roman":"Chunaa zakham gopaal andaakhat sakhat |","meaning_en":"Gopal dealt such a severe wound","page":2577,"meaning_status":"draft","note":"ਗੋਪਾਲ: a name not otherwise explained here; uncertain who is meant."},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਦਾਨੋ ਚੁ ਬੇਖ ਅਜ਼ ਦਰਖ਼ਤ। ੭੨।","roman":"Biaftaad daano chu bekh az darkhat | 72 |","meaning_en":"that the demon fell like a tree torn from its root.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":2577,"lines":[{"gurmukhi":"ਦਿਗਰ ਕਸ ਨਿਯਾਮਦ ਅਜ਼ੋ ਆਰਜ਼ੋ।","roman":"Digar kas niyaamad azo aarzo |","meaning_en":"No one else had any longing","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਆਯਦ ਬਜੰਗੇ ਚੁਨੀ ਮਾਹਰੋ। ੭੩।","roman":"Ki aayad bajange chunee maahro | 73 |","meaning_en":"to come to battle against such a moon-faced one.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":2577,"lines":[{"gurmukhi":"ਸ਼ਹੇ ਚੀਨ ਸਰ ਤਾਜ ਰੰਗੀ ਨਿਹਾਦ।","roman":"Shahe cheen sar taaj rangee nihaad |","meaning_en":"The king of China set a coloured crown on his head,","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਬਲਾਏ ਗੁਬਾਰਸ਼ ਦਹਨ ਬਰ ਕੁਸ਼ਾਦ। ੭੪।","roman":"Balaae gubaarash dahan bar kushaad | 74 |","meaning_en":"and opened the mouth of his storm of calamity.","page":2577,"meaning_status":"draft","note":"uncertain."}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2577,"lines":[{"gurmukhi":"ਸ਼ਬ ਆਮਦ ਯਕੇ ਫ਼ੌਜ ਰਾ ਸਾਜ਼ ਕਰਦ।","roman":"Shab aamad yake fauj raa saaz karad |","meaning_en":"Night came; he arrayed an army","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿ ਦੀਗਰ ਵਜਹ ਬਾਜ਼ੀ ਆਗਾਜ਼ ਕਰਦ। ੭੫।","roman":"Zi deegar vajah baazee aagaaz karad | 75 |","meaning_en":"and began the game in another way.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2577,"lines":[{"gurmukhi":"ਕਿ ਅਫ਼ਸੋਸ ਅਫ਼ਸੋਸ ਹੈ ਹਾਤ ਹਾਤ।","roman":"Ki afsos afsos hai haat haat |","meaning_en":"Alas, alas! Ah, woe, woe","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਅਜ਼ੀਂ ਉਮਰ ਵਜ਼ੀਂ ਜ਼ਿੰਦਗੀ ਜ਼ੀ ਹਯਾਤ। ੭੬।","roman":"Azeen umar vazeen zindgee zee hayaat | 76 |","meaning_en":"for this age, this life, this existence!","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":2577,"lines":[{"gurmukhi":"ਬ ਰੋਜ਼ੇ ਦਿਗਰ ਰਉਸ਼ਨੀਯਤ ਫ਼ਿਕਰ।","roman":"Ba roze digar raushneeyat fikar |","meaning_en":"The next day the radiant one, full of purpose,","page":2577,"meaning_status":"draft","note":"ਰਉਸ਼ਨੀਯਤ ਫ਼ਿਕਰ: read as the sun; uncertain."},{"gurmukhi":"ਬਰ ਔਰੰਗ ਦਰਾਮਦ ਚੁ ਸ਼ਾਹੇ ਦਿਗਰ। ੭੭।","roman":"Bar aurang daraamad chu shaahe digar | 77 |","meaning_en":"came onto the throne like another king.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2577,"lines":[{"gurmukhi":"ਸਿਯਹਿ ਸੂ ਦੁ ਬਰਖ਼ਾਸਤ ਅਜ਼ ਜੋਸ਼ ਜੰਗ।","roman":"Siyhi soo du barkhaasat az josh jang |","meaning_en":"The armies of both sides rose in the fervour of battle;","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਰਵਾਂ ਸ਼ੁਦ ਬ ਹਰ ਗੋਸ਼ਹ ਤੀਰੋ ਤੁਫ਼ੰਗ। ੭੮।","roman":"Ravaan shud ba har goshah teero tufang | 78 |","meaning_en":"arrows and musket-shots flew to every corner.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":2577,"lines":[{"gurmukhi":"ਰਵਾਂਰਵ ਸ਼ੁਦਹ ਕੈਬਰੇ ਕੀਨਹ ਕੋਸ਼।","roman":"Ravaanrav shudah kaibre keenah kosh |","meaning_en":"Arrows of vengeance flew back and forth,","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਬਾਜ਼ੂਏ ਮਰਦਾਂ ਬਰਾਵੁਰਦ ਜੋਸ਼। ੭੯।","roman":"Ki baazooe mardaan baraavurad josh | 79 |","meaning_en":"and the arms of the men burned with zeal.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":2577,"lines":[{"gurmukhi":"ਚੁ ਲਸ਼ਕਰ ਤਮਾਮੀ ਦਰਾਮਦ ਬ ਕਾਮ।","roman":"Chu lashkar tamaamee daraamad ba kaam |","meaning_en":"When the whole army had been slain,","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਯਕੇ ਮਾਂਦ ਓ ਰਾਸਤ ਸੁਭਟ ਸਿੰਘ ਨਾਮ। ੮੦।","roman":"Yake maand o raasat subhat singh naam | 80 |","meaning_en":"one remained, and his name was Subhat Singh.","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2577,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਕਿ ਏ ਸ਼ਾਹ ਰੁਸਤਮ ਜ਼ਮਾਂ।","roman":"Bigoyad ki e shaah rustam zamaan |","meaning_en":"She said, \"O king, Rustam of the age,","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਤੁ ਮਾਰਾ ਬਿਕੁਨ ਯਾ ਬਿਗੀਰੀ ਕਮਾਂ। ੮੧।","roman":"Tu maaraa bikun yaa bigeeree kamaan | 81 |","meaning_en":"either make me yours or take up your bow.\"","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":2577,"lines":[{"gurmukhi":"ਬਗਜ਼ਬ ਅੰਦਰ ਆਮਦ ਚੁ ਸ਼ੇਰੇ ਜ਼ਿਆਂ।","roman":"Bagzab andar aamad chu shere ziaan |","meaning_en":"He flew into a rage like a fierce lion:","page":2577,"meaning_status":"draft"},{"gurmukhi":"ਨ ਪੁਸ਼ਤੇ ਦਿਹਮ ਬਾਨੂਏ ਹਮ ਚੁਨਾ। ੮੨।","roman":"Na pushte diham baanooe ham chunaa | 82 |","meaning_en":"\"I will not turn my back even to such a lady.\"","page":2577,"meaning_status":"draft"}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2579,"lines":[{"gurmukhi":"ਬਪੋਸ਼ੀਦ ਖ਼ੁਫ਼ਤਾਨ ਜੋਸ਼ੀਦ ਜੰਗ।","roman":"Baposheed khuftaan josheed jang |","meaning_en":"He put on his war-coat, eager for battle,","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਬਕੋਸ਼ੀਦ ਚੂੰ ਸ਼ੇਰ ਮਰਦਾਂ ਨਿਹੰਗ। ੮੩।","roman":"Bakosheed choon sher mardaan nihang | 83 |","meaning_en":"and fought like a lion among men, a fearless warrior.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2579,"lines":[{"gurmukhi":"ਬ ਜਾਯਸ਼ ਦਰਾਮਦ ਚੁ ਸ਼ੇਰੇ ਅਜ਼ੀਮ।","roman":"Ba jaayash daraamad chu shere azeem |","meaning_en":"He came to his place like a mighty lion,","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਬ ਕੈਬਰ ਕਮਾਂ ਕਰਦ ਬਾਰਸ਼ ਕਰੀਮ। ੮੪।","roman":"Ba kaibar kamaan karad baarash kareem | 84 |","meaning_en":"and from his bow the generous one rained arrows.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2579,"lines":[{"gurmukhi":"ਚਪੋ ਰਾਸਤ ਓ ਕਰਦ ਖ਼ਮ ਕਰਦ ਰਾਸਤ।","roman":"Chapo raasat o karad kham karad raasat |","meaning_en":"He drew his bow left and right, bending and straightening it;","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਗਰੇਵੇ ਕਮਾਂ ਚਰਖ਼ ਚੀਨੀ ਬਿਖ਼ਾਸਤ। ੮੫।","roman":"Gareve kamaan charakh cheenee bikhaasat | 85 |","meaning_en":"the twang of the bow and the Chinese bow rose up.","page":2579,"meaning_status":"draft","note":"ਚਰਖ਼ ਚੀਨੀ: 'Chinese bow' (crossbow) or 'the wheel of heaven'; uncertain."}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2579,"lines":[{"gurmukhi":"ਹਰਾਂ ਕਸ ਕਿ ਨੇਜ਼ਹ ਬਿਅਫ਼ਤਾਦ ਮੁਸ਼ਤ।","roman":"Haraan kas ki nezah biaftaad mushat |","meaning_en":"Everyone on whom a spear or a fist fell","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਦੁਤਾ ਗਸ਼ਤ ਮੁਸ਼ਤੇ ਹਮੀ ਚਾਰ ਗਸ਼ਤ। ੮੬।","roman":"Dutaa gashat mushte hamee chaar gashat | 86 |","meaning_en":"was bent double, and then fourfold.","page":2579,"meaning_status":"draft","note":"uncertain."}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2579,"lines":[{"gurmukhi":"ਬਿਯਾਵੇਖ਼ਤ ਬਾ ਦੀਗਰੇ ਬਾਜ਼ ਪਰ।","roman":"Biyaavekhat baa deegre baaz par |","meaning_en":"He grappled with the other, like a hawk with spread wings,","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਸੁਰਖ਼ ਅਜ਼ਦਹਾ ਬਰ ਹਮੀ ਸ਼ੇਰ ਨਰ। ੮੭।","roman":"Chu surakh azadhaa bar hamee sher nar | 87 |","meaning_en":"like a red dragon upon a male lion.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2579,"lines":[{"gurmukhi":"ਚੁਨਾ ਬਾਨ ਅਫ਼ਤਾਦ ਤੀਰੋ ਤੁਫ਼ੰਗ।","roman":"Chunaa baan aftaad teero tufang |","meaning_en":"Such shafts, arrows and musket-shots fell","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿਮੀ ਕੁਸ਼ਤ ਗਾਨਸ਼ ਸ਼ੁਦਹ ਲਾਲਹ ਰੰਗ। ੮੮।","roman":"Zimee kushat gaanash shudah laalah rang | 88 |","meaning_en":"that the ground, from the slain, turned the colour of tulips.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2579,"lines":[{"gurmukhi":"ਕੁਨਦ ਤੀਰ ਬਾਰਾਨ ਰੋਜ਼ੇ ਤਮਾਮ।","roman":"Kunad teer baaraan roze tamaam |","meaning_en":"They rained arrows the whole day long;","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਕਸੇ ਰਾ ਨ ਗਸ਼ਤੀਦ ਮਕਸੂਦ ਕਾਮ। ੮੯।","roman":"Kase raa na gashteed maksood kaam | 89 |","meaning_en":"neither attained their aim.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2579,"lines":[{"gurmukhi":"ਅਜ਼ੋ ਜੰਗ ਜ਼ੋ ਮਾਂਦਗੀ ਮਾਂਦਹ ਗਸ਼ਤ।","roman":"Azo jang zo maandgee maandah gashat |","meaning_en":"From the fighting they grew weary and exhausted;","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਹਰਦੋ ਦਰ ਆ ਪਹਿਨ ਦਸਤ। ੯੦।","roman":"Biaftaad hardo dar aa pahin dasat | 90 |","meaning_en":"both fell down there on the open plain.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":2579,"lines":[{"gurmukhi":"ਸ਼ਹਿਨਸ਼ਾਹਿ ਰੂਮੀ ਸਿਪਰ ਦਾਦ ਰੋਇ।","roman":"Shahinshaahi roomee sipar daad roi |","meaning_en":"The emperor of Rum turned his shield-face away,","page":2579,"meaning_status":"draft","note":"Image of sunset: the 'emperor of Rum' (the day, the sun) withdraws; uncertain."},{"gurmukhi":"ਦਿਗਰ ਸ਼ਾਹਿ ਪੈਦਾ ਸ਼ੁਦਹ ਨੇਕ ਖ਼ੋਇ। ੯੧।","roman":"Digar shaahi paidaa shudah nek khoi | 91 |","meaning_en":"and another king of good nature appeared.","page":2579,"meaning_status":"draft","note":"i.e. night or the moon."}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2579,"lines":[{"gurmukhi":"ਨ ਦਰ ਜੰਗ ਆਸੂਦਹ ਸ਼ੁਦ ਯਕ ਜ਼ਮਾਂ।","roman":"Na dar jang aasoodah shud yak zamaan |","meaning_en":"They had not rested from battle for a moment;","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਹਰਦੋ ਚੁਨੀ ਕੁਸ਼ਤਗਾਂ। ੯੨।","roman":"Biaftaad hardo chunee kushatgaan | 92 |","meaning_en":"both fell down like the slain.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2579,"lines":[{"gurmukhi":"ਦਿਗਰ ਰੋਜ਼ ਬਰਖ਼ਾਸਤ ਹਰਦੋ ਬਜੰਗ।","roman":"Digar roz barkhaasat hardo bajang |","meaning_en":"The next day both rose to battle","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਬਿਆਵੇਖ਼ਤ ਬਾ ਯਕ ਦਿਗਰ ਚੂੰ ਨਿਹੰਗ। ੯੩।","roman":"Biaavekhat baa yak digar choon nihang | 93 |","meaning_en":"and grappled with each other like crocodiles.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":2579,"lines":[{"gurmukhi":"ਵਜ਼ਾਂ ਹਰਦੁ ਤਨ ਕੂਜ਼ਹਗਾਨੇ ਸ਼ੁਦਹ।","roman":"Vazaan hardu tan koozahgaane shudah |","meaning_en":"Both their bodies became like pierced pitchers,","page":2579,"meaning_status":"draft","note":"ਕੂਜ਼ਹਗਾਨੇ: read as 'like pitchers'; uncertain."},{"gurmukhi":"ਕਜ਼ਾਂ ਸੀਨਹ ਗਾਹੀਨ ਅਰਵਾ ਸ਼ੁਦਹ। ੯੪।","roman":"Kazaan seenah gaaheen arvaa shudah | 94 |","meaning_en":"as if their souls were leaving through their breasts.","page":2579,"meaning_status":"draft","note":"ਸੀਨਹ ਗਾਹੀਨ ਅਰਵਾ: uncertain."}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":2579,"lines":[{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਚੁ ਮੁਸ਼ਕੀ ਨਿਹੰਗ।","roman":"Ba rakhash andar aamad chu mushkee nihang |","meaning_en":"They came charging on their horses like dark crocodiles,","page":2579,"meaning_status":"draft","note":"ਰਖ਼ਸ਼: 'horse' or 'dancing'; ਮੁਸ਼ਕੀ: 'black'."},{"gurmukhi":"ਬਸੇ ਬੰਗਸੀ ਬੋਜ਼ ਬੰਗੋ ਪਿਲੰਗ। ੯੫।","roman":"Base bangsee boz bango pilang | 95 |","meaning_en":"many Bangashi horses, grey, and spotted like leopards,","page":2579,"meaning_status":"draft","note":"ਬੰਗਸੀ: horses from Bangash; ਬੋਜ਼: grey; uncertain."}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":2579,"lines":[{"gurmukhi":"ਕਿ ਅਬਲਕ ਸਿਯਾਹ ਅਬਲਕੋ ਬੋਜ਼ ਬੋਰ।","roman":"Ki ablak siyaah abalko boz bor |","meaning_en":"piebald, black, dappled, grey and bay;","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਚੁ ਤਾਊਸ ਮੋਰ। ੯੬।","roman":"Ba rakhash andar aamad chu taaoos mor | 96 |","meaning_en":"they came dancing like peacocks.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":2579,"lines":[{"gurmukhi":"ਜ਼ਿਰਹ ਪਾਰਹ ਸ਼ੁਦ ਖ਼ੋਦ ਵ ਖ਼ੁਫ਼ਤਾ ਬਜੰਗ।","roman":"Zirah paarah shud khod va khuftaa bajang |","meaning_en":"Mail was torn, and helmet and coat, in the battle,","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿ ਬਕਤਰ ਜ਼ਿ ਬਰਗਸ਼ਤਵਾਂ ਬਾ ਖ਼ੁਦੰਗ। ੯੭।","roman":"Zi baktar zi baragshatvaan baa khudang | 97 |","meaning_en":"armour and horse-armour, by the arrows.","page":2579,"meaning_status":"draft","note":"ਖ਼ੁਦੰਗ: read as 'khadang' (arrow)."}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2579,"lines":[{"gurmukhi":"ਚੁਨਾ ਤੀਰ ਬਾਰਾਂ ਸ਼ਵਦ ਕਾਰਜ਼ਾਰ।","roman":"Chunaa teer baaraan shavad kaarzaar |","meaning_en":"Such arrows rained in the battle","page":2579,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿ ਬਕਤਰ ਜ਼ਿ ਜ਼ਿਰਹਾ ਬਰਾਰਦ ਸ਼ਰਾਰ। ੯੮।","roman":"Zi baktar zi zirhaa baraarad sharaar | 98 |","meaning_en":"that sparks flew from armour and mail.","page":2579,"meaning_status":"draft"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2581,"lines":[{"gurmukhi":"ਬ ਰਖ਼ਸ਼ ਅੰਦਰ ਆਮਦ ਚੁ ਸ਼ੇਰੇ ਨਿਹੰਗ।","roman":"Ba rakhash andar aamad chu shere nihang |","meaning_en":"They came charging like lions and crocodiles;","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿਮੀ ਗਸ਼ਤਸ਼ੁਦ ਹਮ ਚੁ ਪੁਸ਼ਤੇ ਪਿਲੰਗ। ੯੯।","roman":"Zimee gashatshud ham chu pushte pilang | 99 |","meaning_en":"the ground became like a leopard's back.","page":2581,"meaning_status":"draft","note":"i.e. spotted with blood."}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2581,"lines":[{"gurmukhi":"ਚੁਨਾ ਜ਼੍ਯਾਦਹ ਸ਼ੁਦ ਆਤਸ਼ੇ ਤੀਰ ਬਾਰ।","roman":"Chunaa zyaadah shud aatshe teer baar |","meaning_en":"The fire of raining arrows grew so great","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਅਕਲ ਅਜ਼ ਮਗਜ਼ ਰਫ਼ਤ ਹੋਸ਼ ਅਜ਼ ਦਿਯਾਰ। ੧੦੦।","roman":"Ki akal az magaz rafat hosh az diyaar | 100 |","meaning_en":"that reason left the brain and the senses left the land.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":2581,"lines":[{"gurmukhi":"ਚੁਨਾ ਆਵੇਖ਼ਤ ਹਰਦੋ ਹੁਮਾ ਜਾਇ ਜੰਗ।","roman":"Chunaa aavekhat hardo humaa jaai jang |","meaning_en":"Both grappled so on that battlefield","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਤੇਗ ਅਜ਼ ਮਿਯਾਂ ਗਸ਼ਤ ਤਰਕਸ਼ ਖਤੰਗ। ੧੦੧।","roman":"Ki teg az miyaan gashat tarkash khatang | 101 |","meaning_en":"that swords left their scabbards and arrows their quivers.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":2581,"lines":[{"gurmukhi":"ਚੁਨਾ ਜੰਗ ਕਰਦੰਦ ਸੁਬਹ ਤਾਬ ਸ਼ਾਮ।","roman":"Chunaa jang kardand subah taab shaam |","meaning_en":"So they fought from morning till evening;","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਬਿ ਅਫ਼ਤਾਦ ਮੁਰਛਤ ਨ ਖ਼ੁਰਦੰਦ ਤਆਮ। ੧੦੨।","roman":"Bi aftaad murchhat na khurdand ta'aam | 102 |","meaning_en":"they fell senseless and ate no food.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":2581,"lines":[{"gurmukhi":"ਜਿ ਖ਼ੁਦ ਮਾਂਦਹ ਸ਼ੁਦ ਹਰਦੁ ਦਰ ਜਾਇ ਜੰਗ।","roman":"Ji khud maandah shud hardu dar jaai jang |","meaning_en":"Both were worn out on the battlefield,","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਚੁ ਸ਼ੇਰੋ ਯੀਆਨੋ ਚੁ ਬਾਜ਼ਾ ਪਿਲੰਗ। ੧੦੩।","roman":"Chu shero yeeaano chu baazaa pilang | 103 |","meaning_en":"like fierce lions, and like hawks and leopards.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":2581,"lines":[{"gurmukhi":"ਚੁ ਹਬਸ਼ੀ ਬਰੁਦ ਦੁਜ਼ਦ ਦੀਨਾਰ ਜ਼ਰਦ।","roman":"Chu habshee barud duzad deenaar zarad |","meaning_en":"When the Abyssinian thief carried off the yellow dinar,","page":2581,"meaning_status":"draft","note":"Image of nightfall: dark night takes away the golden sun."},{"gurmukhi":"ਜਹਾਂ ਗਸ਼ਤ ਚੂੰ ਗੁੰਬਜ਼ੇ ਦੂਦ ਗਰਦ। ੧੦੪।","roman":"Jahaan gashat choon gunbze dood garad | 104 |","meaning_en":"the world became like a dome of smoke and dust.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":2581,"lines":[{"gurmukhi":"ਸਿਯਮ ਰੋਜ਼ ਚੌਗਾਂ ਬਿਬੁਰਦ ਆਫ਼ਤਾਬ।","roman":"Siyam roz chaugaan biburad aaftaab |","meaning_en":"On the third day the sun carried off the polo-ball,","page":2581,"meaning_status":"draft","note":"i.e. the sun rose victorious."},{"gurmukhi":"ਜਹਾਂ ਗਸ਼ਤ ਚੂੰ ਰਉਸ਼ਨਸ਼ ਮਾਹਿਤਾਬ। ੧੦੫।","roman":"Jahaan gashat choon raushnash maahitaab | 105 |","meaning_en":"and the world became bright as moonlight.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":2581,"lines":[{"gurmukhi":"ਬੁ ਬਰਖ਼ਾਸਤ ਹਰਦੋ ਅਜ਼ੀਂ ਜਾਇ ਜੰਗ।","roman":"Bu barkhaasat hardo azeen jaai jang |","meaning_en":"Both rose again on that battlefield","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਰਵਾਂ ਕਰਦ ਹਰ ਸੂਇ ਤੀਰੋ ਤੁਫ਼ੰਗ। ੧੦੬।","roman":"Ravaan karad har sooi teero tufang | 106 |","meaning_en":"and sent arrows and musket-shots in every direction.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":2581,"lines":[{"gurmukhi":"ਚੁਨਾ ਗਰਮ ਸ਼ੁਦ ਆਤਸ਼ੇ ਕਾਰਜ਼ਾਰ।","roman":"Chunaa garam shud aatshe kaarzaar |","meaning_en":"So hot grew the fire of battle","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਫ਼ੀਲੇ ਦੁ ਦਹ ਹਜ਼ਾਰ ਆਮਦ ਬ ਕਾਰ। ੧੦੭।","roman":"Ki feele du dah hazaar aamad ba kaar | 107 |","meaning_en":"that twelve thousand elephants were slain.","page":2581,"meaning_status":"draft","note":"ਦੁ ਦਹ ਹਜ਼ਾਰ: read as twelve thousand; could be twenty thousand."}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":2581,"lines":[{"gurmukhi":"ਬ ਕਾਰ ਆਮਦਹ ਅਸਪ ਹਫ਼ਤ ਸਦ ਹਜ਼ਾਰ।","roman":"Ba kaar aamdah asap hafat sad hazaar |","meaning_en":"Seven hundred thousand horses were slain,","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਹਮਹ ਜ੍ਵਾਨ ਸ਼ਾਇਸਤਹ ਨਾਮਦਾਰ। ੧੦੮।","roman":"Hamah jvaan shaaistah naamdaar | 108 |","meaning_en":"all young, worthy and renowned,","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":2581,"lines":[{"gurmukhi":"ਜ਼ਿ ਸਿੰਧੀ ਵ ਅਰਬੀ ਵ ਐਰਾਕ ਰਾਇ।","roman":"Zi sindhee va arbee va airaak raai |","meaning_en":"of Sindhi, Arabian and Iraqi breed;","page":2581,"meaning_status":"draft","note":"ਐਰਾਕ ਰਾਇ: 'Iraq and Rai' or 'Iraqi'; uncertain."},{"gurmukhi":"ਬ ਕਾਰ ਆਮਦਹ ਅਸਪ ਚੂੰ ਬਾਦੁ ਪਾਇ। ੧੦੯।","roman":"Ba kaar aamdah asap choon baadu paai | 109 |","meaning_en":"horses swift as the wind were slain.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":2581,"lines":[{"gurmukhi":"ਬਸੇ ਕੁਸ਼ਤਹ ਸਰਹੰਗ ਸ਼ਾਇਸਤਹ ਸ਼ੇਰ।","roman":"Base kushtah sarhang shaaistah sher |","meaning_en":"Many fine, lion-like officers were slain,","page":2581,"meaning_status":"draft","note":"ਸਰਹੰਗ: 'officer, commander'."},{"gurmukhi":"ਬੇ ਵਕਤੇ ਤਰੱਦਦ ਬਕਾਰੇ ਦਲੇਰ। ੧੧੦।","roman":"Be vakte tarddad bakaare daler | 110 |","meaning_en":"bold in action at the time of struggle.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":2581,"lines":[{"gurmukhi":"ਬ ਗੁਰਰੀਦਨ ਆਮਦ ਦੁ ਅਬਰੇ ਸਿਯਾਹ।","roman":"Ba gurreedan aamad du abre siyaah |","meaning_en":"Two black clouds came thundering;","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਨਮੇ ਖ਼ੂਨ ਮਾਹੀ ਲਕੋ ਤੇਗ ਮਾਹ। ੧੧੧।","roman":"Name khoon maahee lako teg maah | 111 |","meaning_en":"by the sword, the dew of blood reached from the fish to the moon.","page":2581,"meaning_status":"draft","note":"Idiom 'from the fish to the moon': from the depths to the heavens; uncertain."}]},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":2581,"lines":[{"gurmukhi":"ਬਜੰਗ ਅੰਦਰੂੰ ਗਉਗਹੇ ਗਾਜ਼ੀਯਾਂ।","roman":"Bajang androon gaughe gaazeeyaan |","meaning_en":"In the battle rose the uproar of the warriors;","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿਮੀਂ ਤੰਗ ਸ਼ੁਦ ਅਜ਼ ਸੁਮੇ ਤਾਜ਼ੀਯਾਂ। ੧੧੨।","roman":"Zimeen tang shud az sume taazeeyaan | 112 |","meaning_en":"the earth grew narrow under the hooves of the Arab horses.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":2581,"lines":[{"gurmukhi":"ਸੁਮੇ ਬਾਦ ਪਾਂਯਾਂਨ ਫ਼ੌਲਾਦ ਨਾਲ।","roman":"Sume baad paanyaann faulaad naal |","meaning_en":"From the steel-shod hooves of the wind-footed horses","page":2581,"meaning_status":"draft"},{"gurmukhi":"ਜ਼ਿਮੀ ਗਸ਼ਤ ਪੁਸ਼ਤੇ ਪਿਲੰਗੀ ਮਿਸਾਲ। ੧੧੩।","roman":"Zimee gashat pushte pilangee misaal | 113 |","meaning_en":"the ground became like a leopard's back.","page":2581,"meaning_status":"draft"}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":2581,"lines":[{"gurmukhi":"ਚਰਾਗੇ ਜਹਾਨੇ ਖ਼ੁਮਹ ਬਾਦਹ ਖ਼ੁਰਦ।","roman":"Charaage jahaane khumah baadah khurad |","meaning_en":"The lamp of the world drank its wine from the vat,","page":2581,"meaning_status":"draft","note":"i.e. the sun set."},{"gurmukhi":"ਸਰੇ ਤਾਜ ਦੀਗਰ ਬਿਰਾਦਰ ਸਪੁਰਦ। ੧੧੪।","roman":"Sare taaj deegar biraadar sapurad | 114 |","meaning_en":"and handed the crown to its other brother.","page":2581,"meaning_status":"draft","note":"i.e. to the moon."}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":2583,"lines":[{"gurmukhi":"ਬਰੋਜ਼ੇ ਚਹਾਰਮ ਤਪੀਦ ਆਫ਼ਤਾਬ।","roman":"Baroze chahaaram tapeed aaftaab |","meaning_en":"On the fourth day the sun blazed","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬ ਜਿਲਵਹ ਦਰ ਆਵੇਖ਼ਤ ਜਰਰੀਂ ਤਨਾਬ। ੧੧੫।","roman":"Ba jilvah dar aavekhat jarreen tanaab | 115 |","meaning_en":"and in its splendour spread out its golden ropes.","page":2583,"meaning_status":"draft","note":"i.e. its rays."}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":2583,"lines":[{"gurmukhi":"ਦਿਗਰ ਰਵਸ਼ ਮਰਦਾਂਨ ਬਸਤੰਦ ਕਮਰ।","roman":"Digar ravash mardaann bastand kamar |","meaning_en":"Again the men girded their waists in the same way;","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਯਮਾਨੀ ਕਮਰ ਦਾਸਤ ਬਰਰੋ ਪਿਸਰ। ੧੧੬।","roman":"Yamaanee kamar daasat barro pisar | 116 |","meaning_en":"the young man had a Yemeni sword at his waist.","page":2583,"meaning_status":"draft","note":"ਯਮਾਨੀ: a Yemeni blade; uncertain."}]},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":2583,"lines":[{"gurmukhi":"ਚੁ ਹੋਸ਼ ਅੰਦਰ ਆਮਦ ਬ ਜੋਸ਼ੀਦ ਜੰਗ।","roman":"Chu hosh andar aamad ba josheed jang |","meaning_en":"When he came to his senses, eager for battle,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬ ਰੋਸ ਅੰਦਰ ਆਮਦ ਚੁ ਕੋਸ਼ਸ਼ ਪਿਲੰਗ। ੧੧੭।","roman":"Ba ros andar aamad chu koshash pilang | 117 |","meaning_en":"he flew into a rage, fighting like a leopard.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":2583,"lines":[{"gurmukhi":"ਚੁਅਮ ਰੋਜ਼ ਕੁਸ਼ਤੰਦ ਦਹਿ ਹਜ਼ਾਰ ਫ਼ੀਲ।","roman":"Chuam roz kushtand dahi hazaar feel |","meaning_en":"On the fourth day ten thousand elephants were slain,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਦੁ ਦਹਿ ਹਜ਼ਾਰ ਅਸਪੋ ਚੁ ਦਰਯਾਇ ਨੀਲ। ੧੧੮।","roman":"Du dahi hazaar aspo chu daryaai neel | 118 |","meaning_en":"and twelve thousand horses, like the river Nile.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":2583,"lines":[{"gurmukhi":"ਬ ਕਾਰ ਆਮਦਹ ਪਿਯਾਦਹ ਸੀ ਸਦ ਹਜ਼ਾਰ।","roman":"Ba kaar aamdah piyaadah see sad hazaar |","meaning_en":"Three hundred thousand foot-soldiers were slain,","page":2583,"meaning_status":"draft","note":"ਸੀ ਸਦ ਹਜ਼ਾਰ: read as three hundred thousand; uncertain."},{"gurmukhi":"ਜਵਾਂ ਮਰਦ ਸ਼ੇਰਾਨ ਅਜ਼ਮੂਦਹ ਕਾਰ। ੧੧੯।","roman":"Javaan marad sheraan azmoodah kaar | 119 |","meaning_en":"young men, lions, tried in action.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":2583,"lines":[{"gurmukhi":"ਕੁਨਦ ਜ਼ੱਰਹੇ ਰਥ ਚਹਾਰੋ ਹਜ਼ਾਰ।","roman":"Kunad zarrhe rath chahaaro hazaar |","meaning_en":"Four thousand chariots were smashed to pieces,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬ ਸ਼ੇਰ ਅਫ਼ਕਨੋ ਜੰਗ ਆਮੁਖ਼ਤਹ ਕਾਰ। ੧੨੦।","roman":"Ba sher afakno jang aamukhtah kaar | 120 |","meaning_en":"with lion-slaying men practised in war.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":2583,"lines":[{"gurmukhi":"ਕਿ ਅਜ਼ ਚਾਰ ਤੀਰ ਅਸਪ ਕੁਸ਼ਤਸ਼ ਚਹਾਰ।","roman":"Ki az chaar teer asap kushtash chahaar |","meaning_en":"With four arrows she killed his four horses,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਦਿਗਰ ਤੀਰ ਕੁਸ਼ਤਸ਼ ਸਰੇ ਬਹਿਲਦਾਰ। ੧੨੧।","roman":"Digar teer kushtash sare bahildaar | 121 |","meaning_en":"with another arrow she killed the charioteer's head.","page":2583,"meaning_status":"draft","note":"ਸਰੇ ਬਹਿਲਦਾਰ: 'the head charioteer' or 'the charioteer's head'; uncertain."}]},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":2583,"lines":[{"gurmukhi":"ਸਿਯਮ ਤੀਰ ਜ਼ਦ ਹਰਦੋ ਅਬਰੂ ਸ਼ਿਕੰਜ।","roman":"Siyam teer zad hardo abroo shikanj |","meaning_en":"The third arrow she shot between his two knitted brows,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਮਾਰੇ ਬ ਪੇਚੀਦ ਜ਼ਿ ਸਉਦਾਇ ਗੰਜ। ੧੨੨।","roman":"Ki maare ba pecheed zi saudaai ganj | 122 |","meaning_en":"so that he writhed like a snake maddened over treasure.","page":2583,"meaning_status":"draft","note":"uncertain."}]},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":2583,"lines":[{"gurmukhi":"ਚਹਾਰਮ ਬਿਜ਼ਦ ਤੀਰ ਖ਼ਬਰਸ਼ ਨਿਯਾਫ਼ਤ।","roman":"Chahaaram bizad teer khabrash niyaafat |","meaning_en":"She shot a fourth arrow, and he knew nothing more;","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਭਰਮਸ਼ ਬ ਬਰਖ਼ਾਸਤ ਧਰਮਸ਼ ਨ ਤਾਫ਼ਤ। ੧੨੩।","roman":"Ki bharmash ba barkhaasat dharmash na taafat | 123 |","meaning_en":"his doubt arose, yet his dharma did not turn away.","page":2583,"meaning_status":"draft","note":"ਭਰਮਸ਼ ... ਧਰਮਸ਼: uncertain."}]},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":2583,"lines":[{"gurmukhi":"ਬਿਜ਼ਦ ਚੂੰ ਚੁਅਮ ਕੈਬਰੇ ਨਾਜ਼ਨੀਂ।","roman":"Bizad choon chuam kaibre naazneen |","meaning_en":"When the graceful one shot the fourth arrow,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬ ਖ਼ੁਰਦੰਦ ਸ਼ਹਿ ਰਗ ਬਿਅਫ਼ਤਦ ਜ਼ਿਮੀਂ। ੧੨੪।","roman":"Ba khurdand shahi rag biaftad zimeen | 124 |","meaning_en":"it struck the king's jugular, and he fell to the ground.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":2583,"lines":[{"gurmukhi":"ਬਿਦਾਨਿਸਤ ਕਿ ਈਂ ਮਰਦ ਪਯ ਮੁਰਦਹ ਗਸ਼ਤ।","roman":"Bidaanisat ki een marad pay murdah gashat |","meaning_en":"She knew that this man had all but died,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਬੂਮ ਹਮ ਚੁਨੀ ਸ਼ੇਰ ਮਸਤ। ੧੨੫।","roman":"Biaftaad boom ham chunee sher masat | 125 |","meaning_en":"fallen on the ground like a drunken lion.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":2583,"lines":[{"gurmukhi":"ਕਿ ਅਜ਼ ਰਥ ਬਿਯਾਮਦ ਬਰਾਮਦ ਜ਼ਿਮੀ।","roman":"Ki az rath biyaamad baraamad zimee |","meaning_en":"She came down from the chariot onto the ground;","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਖ਼ਰਾਮੀਦਹ ਸ਼ੁਦ ਪੈਕਰੇ ਨਾਜ਼ਨੀ। ੧੨੬।","roman":"Kharaameedah shud paikre naaznee | 126 |","meaning_en":"the graceful one walked forward.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":2583,"lines":[{"gurmukhi":"ਬ ਯਕ ਦਸਤ ਬਰਦਾਸ਼ਤ ਯਕ ਪ੍ਯਾਲਹ ਆਬ।","roman":"Ba yak dasat bardaashat yak pyaalah aab |","meaning_en":"In one hand she held a cup of water,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬਨਿਜ਼ਦੇ ਸ਼ਹਿ ਆਮਦ ਚੁ ਪਰਰਾ ਉਕਾਬ। ੧੨੭।","roman":"Banizde shahi aamad chu parraa ukaab | 127 |","meaning_en":"and came to the king like a winged eagle.","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":2583,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਕਿ ਏ ਸ਼ਾਹਿ ਆਜ਼ਾਦ ਮਰਦ।","roman":"Bigoyad ki e shaahi aazaad marad |","meaning_en":"She said, \"O noble king,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਚਿਰਾ ਖ਼ੁਫ਼ਤਹ ਹਸਤੀ ਤੁ ਦਰ ਖ਼ੂਨ ਗਰਦ। ੧੨੮।","roman":"Chiraa khuftah hastee tu dar khoon garad | 128 |","meaning_en":"why do you lie rolling in blood?","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":2583,"lines":[{"gurmukhi":"ਹੁਮਾ ਜਾਨਜਾਨੀ ਤੁਅਮ ਨੌਜਵਾਂ।","roman":"Humaa jaanjaanee tuam naujvaan |","meaning_en":"I am that dear one of yours, O young man;","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਬਦੀਦਨ ਤੁਰਾ ਆਮਦਮ ਈਜ਼ਮਾਂ। ੧੨੯।","roman":"Badeedan turaa aamdam eezmaan | 129 |","meaning_en":"I have come now to see you.\"","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":2583,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਕਿ ਏ ਬਾਨੂਏ ਨੇਂਕ ਬਖ਼ਤ।","roman":"Bigoyad ki e baanooe nenk bakhat |","meaning_en":"He said, \"O fortunate lady,","page":2583,"meaning_status":"draft"},{"gurmukhi":"ਚਿਰਾ ਤੋ ਬਿਯਾਮਦ ਦਰੀਂ ਜਾਇ ਸਖ਼ਤ। ੧੩੦।","roman":"Chiraa to biyaamad dareen jaai sakhat | 130 |","meaning_en":"why have you come to this cruel place?\"","page":2583,"meaning_status":"draft"}]},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":2585,"lines":[{"gurmukhi":"ਅਗਰ ਮੁਰਦਹ ਬਾਸ਼ੀ ਦਿਯਾਰੇਮ ਲਾਸ।","roman":"Agar murdah baashee diyaarem laas |","meaning_en":"\"If you were dead, I would carry away your body;","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਵਗਰ ਜ਼ਿੰਦਹ ਹਸਤੀ ਬ ਯਜ਼ਦਾਂ ਸੁਪਾਸ। ੧੩੧।","roman":"Vagar zindah hastee ba yazdaan supaas | 131 |","meaning_en":"and if you are alive, thanks be to God.\"","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":2585,"lines":[{"gurmukhi":"ਅਜ਼ਾਂ ਗੁਫ਼ਤਨੀਹਾਂ ਖ਼ੁਸ਼ ਆਮਦ ਸੁਖ਼ਨ।","roman":"Azaan gufatneehaan khush aamad sukhan |","meaning_en":"Her words in this speech pleased him;","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਬਿਗੋਯਦ ਕਿ ਏ ਨਾਜ਼ਨੀ ਸੀਮ ਤਨ। ੧੩੨।","roman":"Bigoyad ki e naaznee seem tan | 132 |","meaning_en":"he said, \"O graceful one, silver-bodied,","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":2585,"lines":[{"gurmukhi":"ਹਰਾਂ ਕਸ ਕਿ ਖ਼ਾਹੀ ਬਿਗੋ ਮਨ ਦਿਹਮ।","roman":"Haraan kas ki khaahee bigo man diham |","meaning_en":"whatever you wish, say it, and I will give it;","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਏ ਸ਼ੇਰ ਦਿਲ ਮਨ ਗੁਲਾਮੇ ਤੁਅਮ। ੧੩੩।","roman":"Ki e sher dil man gulaame tuam | 133 |","meaning_en":"O lion-hearted one, I am your slave.\"","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":2585,"lines":[{"gurmukhi":"ਖ਼ੁਦਾਵੰਦ ਬਾਸੀ ਤੁ ਏ ਕਾਰ ਸਖ਼ਤ।","roman":"Khudaavand baasee tu e kaar sakhat |","meaning_en":"\"Be my lord, O you who are strong in action,","page":2585,"meaning_status":"draft","note":"Speaker inferred: the lady."},{"gurmukhi":"ਕਿ ਮਾਰਾ ਬ ਯਕ ਬਾਰ ਕੁਨ ਨੇਕ ਬਖ਼ਤ। ੧੩੪।","roman":"Ki maaraa ba yak baar kun nek bakhat | 134 |","meaning_en":"and at once make me fortunate.\"","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":2585,"lines":[{"gurmukhi":"ਬਿਜ਼ਦ ਪੁਸ਼ਤ ਪਾਓ ਕੁਸ਼ਾਦਸ਼ ਬ ਚਸ਼ਮ।","roman":"Bizad pushat paao kushaadash ba chasham |","meaning_en":"She touched the back of his foot, and he opened his eyes,","page":2585,"meaning_status":"draft","note":"ਬਿਜ਼ਦ ਪੁਸ਼ਤ ਪਾਓ: literal; as a Persian idiom it can mean 'spurned'; ਬ ਚਸ਼ਮ may mean 'gladly'; uncertain."},{"gurmukhi":"ਹਮਹ ਰਵਸ਼ ਸ਼ਾਹਾਨ ਪੇਸ਼ੀਨ ਰਸ਼ਮ। ੧੩੫।","roman":"Hamah ravash shaahaan pesheen rasham | 135 |","meaning_en":"in the manner of all the kings of old.","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":2585,"lines":[{"gurmukhi":"ਬਿਅਫ਼ਤਾਦ ਬਰ ਰਥ ਬਿਆਵੁਰਦ ਜਾਂ।","roman":"Biaftaad bar rath biaavurad jaan |","meaning_en":"He was laid on the chariot, and she brought him back to life;","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਬਿਜ਼ਦ ਨਉਬਤਸ਼ ਸ਼ਾਹਿ ਸ਼ਾਹੇ ਜ਼ਮਾਂ। ੧੩੬।","roman":"Bizad naubtash shaahi shaahe zamaan | 136 |","meaning_en":"the king of kings of the age had his drums beaten.","page":2585,"meaning_status":"draft","note":"ਨਉਬਤ: the royal drum."}]},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":2585,"lines":[{"gurmukhi":"ਬਹੋਸ਼ ਅੰਦਰ ਆਮਦ ਦੁ ਚਸ਼ਮਸ਼ ਕੁਸ਼ਾਦ।","roman":"Bahosh andar aamad du chashmash kushaad |","meaning_en":"He came to his senses and opened both eyes,","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਬਿਗੋਯਦ ਕਿਰਾ ਜਾਇ ਮਾਰਾ ਨਿਹਾਦ। ੧੩੭।","roman":"Bigoyad kiraa jaai maaraa nihaad | 137 |","meaning_en":"and said, \"Who has laid me in this place?\"","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":2585,"lines":[{"gurmukhi":"ਬਿਗੋਯਦ ਤੁਰਾ ਜ਼ਫ਼ਰ ਜੰਗ ਯਾਫ਼ਤਮ।","roman":"Bigoyad turaa zafar jang yaaftam |","meaning_en":"She said, \"I have won the battle against you;","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਬ ਕਾਰੇ ਸ਼ੁਮਾ ਕਤ ਖ਼ੁਦਾ ਯਾਫ਼ਤਮ। ੧੩੮।","roman":"Ba kaare shumaa kat khudaa yaaftam | 138 |","meaning_en":"through your deeds I have found my husband.\"","page":2585,"meaning_status":"draft","note":"ਕਤ ਖ਼ੁਦਾ: read as 'kadkhuda' (master of the house, husband)."}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":2585,"lines":[{"gurmukhi":"ਪਸ਼ੇਮਾਂ ਸ਼ਵਦ ਸੁਖ਼ਨ ਗੁਫ਼ਤਨ ਫ਼ਜ਼ੂਲ।","roman":"Pashemaan shavad sukhan guftan fazool |","meaning_en":"He said, \"One who speaks idle words comes to regret;","page":2585,"meaning_status":"draft","note":"Speaker inferred."},{"gurmukhi":"ਹਰਾਂ ਕਸ ਤੁ ਗੋਈ ਕਿ ਬਰ ਮਨ ਕਬੂਲ। ੧੩੯।","roman":"Haraan kas tu goee ki bar man kabool | 139 |","meaning_en":"whatever you say is acceptable to me.\"","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":2585,"lines":[{"gurmukhi":"ਬਿਦਿਹ ਸਾਕੀਯਾ ਜਾਮ ਫੇਰੋਜ਼ਹ ਫ਼ਾਮ।","roman":"Bidih saakeeyaa jaam pherozah faam |","meaning_en":"Give me, O cup-bearer, the turquoise-coloured cup,","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਮਾ ਰਾ ਬ ਕਾਰ ਅਸਤ ਰੋਜ਼ੇ ਤਮਾਮ। ੧੪੦।","roman":"Ki maa raa ba kaar asat roze tamaam | 140 |","meaning_en":"which I need all day long.","page":2585,"meaning_status":"draft"}]},{"type":"verse","number":[141,4],"number_text":"੧੪੧। ੪।","page":2585,"lines":[{"gurmukhi":"ਤੁ ਮਾਰਾ ਬਿਦਿਹ ਤਾ ਸ਼ਵਮ ਤਾਜ਼ਹ ਦਿਲ।","roman":"Tu maaraa bidih taa shavam taazah dil |","meaning_en":"Give it to me, that my heart may be refreshed,","page":2585,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਗੌਹਰ ਬਿਆਰੇਮ ਆਲੂਦਹ ਗਿਲ। ੧੪੧। ੪।","roman":"Ki gauhar biaarem aaloodah gil | 141 | 4 |","meaning_en":"and I may bring out the jewel from the mud.","page":2585,"meaning_status":"draft"}]}],"ending":null});
